	private static final class ReplayBarrierFunction implements Function {
		private final String functionIri;
		private final CountDownLatch firstInvocation = new CountDownLatch(1);
		private final CountDownLatch releaseFirstInvocation = new CountDownLatch(1);
		private final AtomicInteger invocationCount = new AtomicInteger();

		private ReplayBarrierFunction(String functionIri) {
			this.functionIri = functionIri;
		}

		@Override
		public String getURI() {
			return functionIri;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			return valueFactory.createLiteral(true);
		}

		@Override
		public Value evaluate(TripleSource tripleSource, Value... args) throws ValueExprEvaluationException {
			invocationCount.incrementAndGet();
			firstInvocation.countDown();
			try {
				if (!releaseFirstInvocation.await(20, TimeUnit.SECONDS)) {
					throw new ValueExprEvaluationException("Timed out waiting to release the replay barrier");
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new ValueExprEvaluationException("Interrupted while waiting at the replay barrier", e);
			}
			return tripleSource.getValueFactory().createLiteral(true);
		}

		private boolean awaitFirstInvocation() throws InterruptedException {
			return firstInvocation.await(10, TimeUnit.SECONDS);
		}

		private void releaseFirstInvocation() {
			releaseFirstInvocation.countDown();
		}

		private int invocationCount() {
			return invocationCount.get();
		}
	}

	private static final class RetryCapFunction implements Function {
		private final String functionIri;
		private final CountDownLatch firstInvocation = new CountDownLatch(1);
		private final CountDownLatch secondInvocation = new CountDownLatch(1);
		private final CountDownLatch releaseFirstInvocation = new CountDownLatch(1);
		private final CountDownLatch releaseSecondInvocation = new CountDownLatch(1);
		private final AtomicInteger invocationCount = new AtomicInteger();

		private RetryCapFunction(String functionIri) {
			this.functionIri = functionIri;
		}

		@Override
		public String getURI() {
			return functionIri;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			return valueFactory.createLiteral(true);
		}

		@Override
		public Value evaluate(TripleSource tripleSource, Value... args) throws ValueExprEvaluationException {
			int invocation = invocationCount.incrementAndGet();
			CountDownLatch started = invocation == 1 ? firstInvocation
					: invocation == 2 ? secondInvocation
							: null;
			CountDownLatch release = invocation == 1 ? releaseFirstInvocation
					: invocation == 2 ? releaseSecondInvocation
							: null;
			if (started != null) {
				started.countDown();
				try {
					if (!release.await(30, TimeUnit.SECONDS)) {
						throw new ValueExprEvaluationException("Timed out waiting to release retry-cap barrier");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new ValueExprEvaluationException("Interrupted while waiting at retry-cap barrier", e);
				}
			}
			return tripleSource.getValueFactory().createLiteral(true);
		}

		private boolean awaitFirstInvocation() throws InterruptedException {
			return firstInvocation.await(10, TimeUnit.SECONDS);
		}

		private boolean awaitSecondInvocation() throws InterruptedException {
			return secondInvocation.await(15, TimeUnit.SECONDS);
		}

		private void releaseFirstInvocation() {
			releaseFirstInvocation.countDown();
		}

		private void releaseSecondInvocation() {
			releaseSecondInvocation.countDown();
		}

		private int invocationCount() {
			return invocationCount.get();
		}
	}

	private static final class FailingFirstInvocationFunction implements Function {
		private final String functionIri;
		private final CountDownLatch firstInvocation = new CountDownLatch(1);
		private final CountDownLatch releaseFirstInvocation = new CountDownLatch(1);
		private final AtomicInteger invocationCount = new AtomicInteger();

		private FailingFirstInvocationFunction(String functionIri) {
			this.functionIri = functionIri;
		}

		@Override
		public String getURI() {
			return functionIri;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			return valueFactory.createLiteral(true);
		}

		@Override
		public Value evaluate(TripleSource tripleSource, Value... args) throws ValueExprEvaluationException {
			if (invocationCount.incrementAndGet() == 1) {
				firstInvocation.countDown();
				try {
					if (!releaseFirstInvocation.await(20, TimeUnit.SECONDS)) {
						throw new ValueExprEvaluationException("Timed out waiting to release failure barrier");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new ValueExprEvaluationException("Interrupted while waiting at failure barrier", e);
				}
				throw new IllegalStateException("sentinel query failure");
			}
			return tripleSource.getValueFactory().createLiteral(true);
		}

		private boolean awaitFirstInvocation() throws InterruptedException {
			return firstInvocation.await(10, TimeUnit.SECONDS);
		}

		private void releaseFirstInvocation() {
			releaseFirstInvocation.countDown();
		}

		private int invocationCount() {
			return invocationCount.get();
		}
	}

	private static final class CancellingFirstInvocationFunction implements Function {
		private final String functionIri;
		private final CountDownLatch firstInvocation = new CountDownLatch(1);
		private final CountDownLatch releaseFirstInvocation = new CountDownLatch(1);
		private final AtomicInteger invocationCount = new AtomicInteger();

		private CancellingFirstInvocationFunction(String functionIri) {
			this.functionIri = functionIri;
		}

		@Override
		public String getURI() {
			return functionIri;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			return valueFactory.createLiteral(true);
		}

		@Override
		public Value evaluate(TripleSource tripleSource, Value... args) throws ValueExprEvaluationException {
			if (invocationCount.incrementAndGet() == 1) {
				firstInvocation.countDown();
				try {
					if (!releaseFirstInvocation.await(20, TimeUnit.SECONDS)) {
						throw new ValueExprEvaluationException("Timed out waiting to release cancellation barrier");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new ValueExprEvaluationException("Interrupted while waiting at cancellation barrier", e);
				}
				throw new QueryInterruptedException("sentinel query cancellation");
			}
			return tripleSource.getValueFactory().createLiteral(true);
		}

		private boolean awaitFirstInvocation() throws InterruptedException {
			return firstInvocation.await(10, TimeUnit.SECONDS);
		}

		private void releaseFirstInvocation() {
			releaseFirstInvocation.countDown();
		}

		private int invocationCount() {
			return invocationCount.get();
		}
	}
